import{_ as e,o,c as d,a2 as r}from"./chunks/framework.LX5S0jbT.js";const m=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"configuration.md","filePath":"configuration.md"}'),i={name:"configuration.md"};function s(a,t,n,c,l,p){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Pi supports user-level and project configuration. User-level configuration lives in the agent directory, which defaults to <code>~/.pi/agent</code>. Project configuration lives in <code>.pi</code> under the working directory and loads after <a href="./security.html#understand-project-trust">project trust</a> is granted. The only exception is <code>sessionDir</code>, which Pi reads before resolving trust so it can locate sessions.</p><p>In interactive mode, use <code>/settings</code> to change common preferences. For other options, ask Pi to update the configuration or edit the relevant files directly. Run <code>/reload</code> after manually changing settings, keybindings, instructions, or resources.</p><h2 id="agent-directory" tabindex="-1">Agent directory <a class="header-anchor" href="#agent-directory" aria-label="Permalink to &quot;Agent directory&quot;">​</a></h2><p>The agent directory is shown as <code>&lt;agent-dir&gt;</code> below. Set its location with the <code>PI_CODING_AGENT_DIR</code> environment variable or the SDK&#39;s <a href="./sdk.html"><code>agentDir</code></a> option.</p><table tabindex="0"><thead><tr><th>Path</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>&lt;agent-dir&gt;/settings.json</code></td><td>User-level <a href="./settings.html">settings</a>, including preferences, defaults, resource paths, and Pi package declarations.</td></tr><tr><td><code>&lt;agent-dir&gt;/keybindings.json</code></td><td>Custom terminal UI and application <a href="./keybindings.html">keybindings</a>.</td></tr><tr><td><code>&lt;agent-dir&gt;/mcp.json</code></td><td><a href="./mcp.html">MCP servers</a> available in every project.</td></tr><tr><td><code>&lt;agent-dir&gt;/models.json</code></td><td><a href="./models.html#configure-a-compatible-endpoint">Compatible endpoints, models, and model overrides</a>.</td></tr><tr><td><code>&lt;agent-dir&gt;/auth.json</code></td><td>Saved API keys and OAuth credentials.</td></tr><tr><td><code>&lt;agent-dir&gt;/AGENTS.override.md</code>, <code>AGENTS.md</code>, <code>AGENTS.MD</code>, <code>CLAUDE.md</code>, or <code>CLAUDE.MD</code></td><td>User instructions applied across working directories.</td></tr><tr><td><code>&lt;agent-dir&gt;/SYSTEM.md</code></td><td>Replaces Pi’s default system prompt.</td></tr><tr><td><code>&lt;agent-dir&gt;/APPEND_SYSTEM.md</code></td><td>Adds instructions to Pi’s system prompt.</td></tr><tr><td><code>&lt;agent-dir&gt;/extensions/</code></td><td>User <a href="./extensions.html">extensions</a>.</td></tr><tr><td><code>&lt;agent-dir&gt;/skills/</code></td><td>User <a href="./skills.html">skills</a> and supporting files.</td></tr><tr><td><code>&lt;agent-dir&gt;/prompts/</code></td><td>User <a href="./prompt-templates.html">prompt templates</a> exposed as slash commands.</td></tr><tr><td><code>&lt;agent-dir&gt;/themes/</code></td><td>User <a href="./themes.html">theme</a> files.</td></tr></tbody></table><h2 id="project-pi-directory" tabindex="-1">Project <code>.pi</code> directory <a class="header-anchor" href="#project-pi-directory" aria-label="Permalink to &quot;Project `.pi` directory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>.pi/settings.json</code></td><td>Project-level <a href="./settings.html">settings</a>, resource paths, and Pi package declarations.</td></tr><tr><td><code>.pi/mcp.json</code></td><td>Project <a href="./mcp.html">MCP servers</a>.</td></tr><tr><td><code>.pi/SYSTEM.md</code></td><td>Replaces the system prompt for the project.</td></tr><tr><td><code>.pi/APPEND_SYSTEM.md</code></td><td>Adds project-specific instructions to the system prompt.</td></tr><tr><td><code>.pi/extensions/</code></td><td>Project extensions.</td></tr><tr><td><code>.pi/skills/</code></td><td>Project skills and supporting files.</td></tr><tr><td><code>.pi/prompts/</code></td><td>Project prompt templates exposed as slash commands.</td></tr><tr><td><code>.pi/themes/</code></td><td>Project theme files.</td></tr></tbody></table><p>For <code>SYSTEM.md</code> and <code>APPEND_SYSTEM.md</code>, the trusted project file takes precedence over the corresponding agent-directory file. Files with the same name are not combined.</p><h2 id="context-files" tabindex="-1">Context files <a class="header-anchor" href="#context-files" aria-label="Permalink to &quot;Context files&quot;">​</a></h2><p>Context files are separate from project <code>.pi</code> configuration. Pi loads them from the agent directory, the working directory, and its parent directories. A context file applies whenever Pi runs in its directory or anywhere below it.</p><p>An <code>AGENTS.override.md</code> replaces <code>AGENTS.md</code> or <code>CLAUDE.md</code> only in the same directory. It does not suppress context files from the agent directory or other directories.</p><p>Context-file discovery does not require project trust.</p>',13)])])}const g=e(i,[["render",s]]);export{m as __pageData,g as default};
